<?php
session_start();
if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}
require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/../config/order_notifications.php';
$userId=(int)$_SESSION['user_id'];
if(empty($_SESSION['seller_market_csrf']))$_SESSION['seller_market_csrf']=bin2hex(random_bytes(24));
$message='';$error='';

function sellerOwnsOrder(PDO $pdo,int $orderId,int $userId):?array{
    $q=$pdo->prepare("SELECT o.* FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN books b ON b.book_id=oi.book_id WHERE o.order_id=? AND b.seller_type='user' AND b.seller_id=? LIMIT 1");
    $q->execute([$orderId,$userId]);return $q->fetch(PDO::FETCH_ASSOC)?:null;
}
function notifyBuyer(PDO $pdo,array $order,string $title,string $message):void{
    wanawanNotifyOrderBuyer($pdo,$order,$title,$message);
}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($_SESSION['seller_market_csrf'],(string)($_POST['csrf_token']??'')))$error='ไม่สามารถยืนยันคำขอได้ กรุณาลองใหม่';
    else{
        $orderId=(int)($_POST['order_id']??0);$order=sellerOwnsOrder($pdo,$orderId,$userId);
        if(!$order)$error='ไม่พบคำสั่งซื้อที่คุณมีสิทธิ์จัดการ';
        elseif(isset($_POST['update_status'])){
            $status=(string)($_POST['status']??'');
            $map=[
                'delivered'=>["shipping_status='delivered'",'คำสั่งซื้อสำเร็จแล้ว','ผู้ขายอัปเดตว่าสินค้าจัดส่งสำเร็จแล้ว'],
                'cancelled'=>["payment_status='cancelled',shipping_status='cancelled'",'คำสั่งซื้อถูกยกเลิก','ผู้ขายยกเลิกคำสั่งซื้อ กรุณาติดต่อผู้ขายหากต้องการรายละเอียด']
            ];
            if(!isset($map[$status]))$error='สถานะที่เลือกไม่ถูกต้อง';
            else{[$set,$title,$body]=$map[$status];$pdo->beginTransaction();try{$pdo->prepare("UPDATE orders SET $set WHERE order_id=?")->execute([$orderId]);notifyBuyer($pdo,$order,$title,$body);$pdo->commit();$message='อัปเดตสถานะและแจ้งผู้ซื้อเรียบร้อยแล้ว';}catch(Throwable $e){$pdo->rollBack();$error='ไม่สามารถอัปเดตสถานะได้';}}
        }elseif(isset($_POST['save_tracking'])){
            $courier=trim((string)($_POST['courier']??''));$tracking=trim((string)($_POST['tracking_number']??''));
            if($order['payment_status']!=='paid')$error='กรุณาตรวจสอบสลิปให้ผ่านก่อนบันทึกเลขพัสดุ';
            elseif($courier===''||!preg_match('/^[A-Za-z0-9\-]{5,100}$/',$tracking))$error='กรุณากรอกบริษัทขนส่งและเลขพัสดุให้ถูกต้อง';
            else{$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO order_shipments(order_id,seller_type,seller_id,courier,tracking_number,status,shipped_at) VALUES(?,'user',?,?,?,'shipped',NOW()) ON DUPLICATE KEY UPDATE courier=VALUES(courier),tracking_number=VALUES(tracking_number),status='shipped',shipped_at=NOW()")->execute([$orderId,$userId,$courier,$tracking]);$pdo->prepare("UPDATE orders SET shipping_status='shipped',shipping_courier=?,tracking_number=?,shipped_at=NOW() WHERE order_id=?")->execute([$courier,$tracking,$orderId]);notifyBuyer($pdo,$order,'ผู้ขายจัดส่งสินค้าแล้ว','จัดส่งผ่าน '.$courier.' เลขพัสดุ '.$tracking);$pdo->commit();$message='บันทึกเลขพัสดุและแจ้งผู้ซื้อเรียบร้อยแล้ว';}catch(Throwable $e){$pdo->rollBack();$error='ไม่สามารถบันทึกข้อมูลจัดส่งได้';}}
        }
    }
}

$tab=$_GET['tab']??'all';$where="b.seller_type='user' AND b.seller_id=:uid";
if($tab==='packing')$where.=" AND o.payment_status='paid' AND o.shipping_status IN('pending','packing')";elseif($tab==='shipped')$where.=" AND o.shipping_status='shipped'";elseif($tab==='done')$where.=" AND o.shipping_status='delivered'";
elseif($tab==='cancelled')$where.=" AND (o.payment_status='cancelled' OR o.shipping_status IN ('cancelled','returned'))";
$q=$pdo->prepare("SELECT DISTINCT o.* FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN books b ON b.book_id=oi.book_id WHERE $where ORDER BY o.created_at DESC");$q->execute([':uid'=>$userId]);$orders=$q->fetchAll(PDO::FETCH_ASSOC);
$iq=$pdo->prepare("SELECT oi.*,b.title,b.author,b.image_cover FROM order_items oi JOIN books b ON b.book_id=oi.book_id WHERE oi.order_id=? AND b.seller_type='user' AND b.seller_id=?");
foreach($orders as &$o){$iq->execute([$o['order_id'],$userId]);$o['items']=$iq->fetchAll(PDO::FETCH_ASSOC);}unset($o);
$sq=$pdo->prepare("SELECT COUNT(*) total,SUM(payment_status='paid' AND shipping_status IN('pending','packing')) paid,SUM(shipping_status='shipped') shipping,SUM(shipping_status='delivered') completed,SUM(payment_status='cancelled' OR shipping_status IN('cancelled','returned')) cancelled FROM (SELECT DISTINCT o.* FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN books b ON b.book_id=oi.book_id WHERE b.seller_type='user' AND b.seller_id=?) x");$sq->execute([$userId]);$stat=$sq->fetch(PDO::FETCH_ASSOC)?:[];
function smImg(?string $v):?string{if(!$v)return null;$v=ltrim(str_replace('\\','/',$v),'/');return preg_match('#^https?://#',$v)?$v:(str_starts_with($v,'uploads/')?'/pages/'.$v:'/assets/image/books/'.$v);}
function smSlip(?string $v):?string{if(!$v)return null;$v=ltrim(str_replace('\\','/',$v),'/');return '/pages/'.$v;}
function smStatus(array $o):array{if($o['payment_status']==='cancelled'||in_array($o['shipping_status'],['cancelled','returned'],true))return['ยกเลิกแล้ว','cancel'];if($o['shipping_status']==='delivered')return['สำเร็จแล้ว','done'];if($o['shipping_status']==='shipped')return['กำลังจัดส่ง','ship'];if($o['payment_status']==='paid')return['รอจัดส่ง','paid'];return['รอชำระ','wait'];}
$profile_active='market';
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ตลาดซื้อขายหนังสือ - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>
*{box-sizing:border-box}.account{display:flex;min-height:820px}.market{flex:1;max-width:1120px;margin:0 auto;padding:42px 38px 90px}.title{font-size:34px;color:var(--secondary-color)}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:22px 0}.stat{border:1px solid #d5d5ce;border-radius:13px;padding:16px 8px;text-align:center;background:#fff}.stat strong{display:block;font-size:27px;color:var(--secondary-color)}.tabs{display:flex;gap:4px;flex-wrap:wrap;margin:20px 0}.tabs a{padding:10px 15px;border-radius:20px;text-decoration:none;color:#706861}.tabs a.active{background:var(--secondary-color);color:#fff}.notice{padding:13px 17px;border-radius:8px;margin-bottom:16px}.ok{background:#e9f4e5;color:#39703a}.bad{background:#fde5e1;color:#a33}.table-wrap{border:1px solid #c7d0ca;border-radius:14px;background:#fff;overflow:auto;box-shadow:0 2px 5px #0001}.orders{width:100%;border-collapse:collapse;min-width:850px}.orders th,.orders td{padding:14px 12px;text-align:left;border-bottom:1px solid #e2e2dc;vertical-align:middle}.orders th{color:#3f6740}.book-cell{display:flex;gap:11px;align-items:center}.cover{width:48px;height:65px;object-fit:cover;border-radius:4px;background:#f8e8df}.price{font-weight:700;color:var(--secondary-color)}.badge{display:inline-block;border-radius:14px;padding:5px 11px;background:#ffe0dc;color:#bc443d;font-size:12px;font-weight:700}.actions{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--secondary-color);background:var(--secondary-color);color:#fff;border-radius:8px;padding:9px 12px;font:inherit;cursor:pointer}.btn.outline{background:#fff;color:var(--secondary-color)}.empty{text-align:center;padding:90px;color:#897f78}.modal{position:fixed;inset:0;background:#211a174d;display:none;align-items:center;justify-content:center;padding:20px;z-index:9999}.modal.open{display:flex}.modal-box{width:min(900px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:16px;padding:27px;box-shadow:0 18px 60px #0003}.modal-title{margin-top:0;color:var(--secondary-color);border-bottom:1px solid #ddd;padding-bottom:13px}.detail-grid{display:grid;grid-template-columns:1fr 320px;gap:24px}.detail-card{border:1px solid #ddd;border-radius:12px;padding:18px}.slip{width:100%;max-height:430px;object-fit:contain;background:#f8f5f2;border-radius:9px}.field{margin:14px 0}.field label{display:block;font-weight:700;color:var(--secondary-color);margin-bottom:6px}.field input{width:100%;padding:12px;border:1px solid #ccc;border-radius:8px;font:inherit}.modal-actions{display:flex;gap:9px;margin-top:18px}.modal-actions>*{flex:1}.status-forms{display:flex;gap:7px;flex-wrap:wrap;margin-top:18px}.status-forms form{display:inline}.close{background:#fff;color:#a33}.hidden{display:none}@media(max-width:900px){.stats{grid-template-columns:repeat(3,1fr)}.detail-grid{grid-template-columns:1fr}}@media(max-width:700px){.account{display:block}.market{padding:25px 14px}.stats{grid-template-columns:repeat(2,1fr)}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><div class="account"><?php require __DIR__.'/../components/profile_sidebar.php';?><main class="market"><h1 class="title">ตลาดซื้อขายหนังสือ</h1><div class="stats"><?php foreach(['total'=>'คำสั่งซื้อ','paid'=>'รอจัดส่ง','shipping'=>'กำลังจัดส่ง','completed'=>'สำเร็จแล้ว','cancelled'=>'ยกเลิก/คืนสินค้า'] as $key=>$label):?><div class="stat"><strong><?=number_format((int)($stat[$key]??0))?></strong><?=$label?></div><?php endforeach;?></div><?php if($message):?><div class="notice ok"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=htmlspecialchars($error)?></div><?php endif;?><nav class="tabs"><?php foreach(['all'=>'ทั้งหมด','packing'=>'รอจัดส่ง','shipped'=>'กำลังจัดส่ง','done'=>'สำเร็จ','cancelled'=>'ยกเลิก'] as $k=>$v):?><a class="<?=$tab===$k?'active':''?>" href="?tab=<?=$k?>"><?=$v?></a><?php endforeach;?></nav><?php if(!$orders):?><div class="empty">ยังไม่มีคำสั่งซื้อในหมวดนี้</div><?php else:?><div class="table-wrap"><table class="orders"><thead><tr><th>รูปสินค้าและชื่อหนังสือ</th><th>ชื่อผู้แต่ง</th><th>วันที่สั่งซื้อ</th><th>ราคา</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><?php foreach($orders as $o):[$status,$class]=smStatus($o);$first=$o['items'][0]??[];?><tr><td><div class="book-cell"><?php if($img=smImg($first['image_cover']??null)):?><img class="cover" src="<?=htmlspecialchars($img)?>" alt=""><?php endif;?><div><strong><?=htmlspecialchars($first['title']??'หนังสือ')?></strong><?php if(count($o['items'])>1):?><small> และอีก <?=count($o['items'])-1?> รายการ</small><?php endif;?><br><small>#<?=htmlspecialchars($o['order_number'])?></small></div></div></td><td><?=htmlspecialchars($first['author']??'-')?></td><td><?=date('d/m/Y',strtotime($o['created_at']))?></td><td class="price">฿<?=number_format(array_sum(array_map(fn($i)=>$i['price_at_purchase']*$i['quantity'],$o['items'])),2)?></td><td><span class="badge"><?=$status?></span></td><td><div class="actions"><button class="btn detail-btn" data-detail='<?=htmlspecialchars(json_encode(['order'=>$o,'slip'=>smSlip($o['payment_slip_url']??null)],JSON_UNESCAPED_UNICODE),ENT_QUOTES)?>'>ดูรายละเอียด</button><?php if($o['payment_status']==='paid'&&!in_array($o['shipping_status'],['shipped','delivered','cancelled','returned'],true)):?><button class="btn outline ship-btn" data-order="<?=$o['order_id']?>" data-number="<?=htmlspecialchars($o['order_number'])?>">ข้อมูลการจัดส่ง</button><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></main></div><?php require __DIR__.'/../components/footer.php';?>
<div class="modal" id="detailModal"><div class="modal-box"><h2 class="modal-title">รายละเอียดคำสั่งซื้อ</h2><div class="detail-grid"><div class="detail-card"><h3 id="dNumber"></h3><div id="dItems"></div><hr><strong>ผู้รับสินค้า</strong><p id="dBuyer"></p><strong>ที่อยู่จัดส่ง</strong><p id="dAddress"></p><div class="status-forms" id="statusForms"></div></div><div class="detail-card"><h3>หลักฐานการชำระเงิน</h3><img id="dSlip" class="slip hidden" alt="สลิปการชำระเงิน"><p id="noSlip">ผู้ซื้อยังไม่ได้แนบสลิป</p></div></div><div class="modal-actions"><button class="btn close" type="button" data-close>ปิด</button></div></div></div>
<div class="modal" id="shippingModal"><div class="modal-box" style="width:min(620px,100%)"><h2 class="modal-title">กรอกข้อมูลการจัดส่งสินค้า</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['seller_market_csrf'])?>"><input type="hidden" name="order_id" id="shipOrderId"><p id="shipNumber"></p><div class="field"><label>บริษัทขนส่ง</label><input name="courier" required placeholder="เช่น ไปรษณีย์ไทย, Flash Express"></div><div class="field"><label>เลขพัสดุ (Tracking Number)</label><input name="tracking_number" required maxlength="100"></div><div class="modal-actions"><button class="btn" name="save_tracking">บันทึกและแจ้งผู้ซื้อ</button><button class="btn close" type="button" data-close>ยกเลิก</button></div></form></div></div>
<script>
const csrf=<?=json_encode($_SESSION['seller_market_csrf'])?>,detailModal=document.getElementById('detailModal'),shippingModal=document.getElementById('shippingModal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
document.querySelectorAll('.detail-btn').forEach(btn=>btn.addEventListener('click',()=>{const d=JSON.parse(btn.dataset.detail),o=d.order;document.getElementById('dNumber').textContent='คำสั่งซื้อ #'+o.order_number;document.getElementById('dBuyer').textContent=o.shipping_name+' · '+o.shipping_phone;document.getElementById('dAddress').textContent=o.shipping_address;document.getElementById('dItems').innerHTML=o.items.map(i=>`<p><strong>${esc(i.title)}</strong> × ${i.quantity} <span class="price">฿${Number(i.price_at_purchase*i.quantity).toLocaleString()}</span></p>`).join('');const img=document.getElementById('dSlip'),none=document.getElementById('noSlip');if(d.slip){img.src=d.slip;img.classList.remove('hidden');none.classList.add('hidden')}else{img.classList.add('hidden');none.classList.remove('hidden')}let buttons='';if(o.shipping_status==='shipped')buttons+=form(o.order_id,'delivered','จัดส่งสำเร็จ');if(!['delivered','cancelled','returned'].includes(o.shipping_status))buttons+=form(o.order_id,'cancelled','ยกเลิกคำสั่งซื้อ','outline');document.getElementById('statusForms').innerHTML=buttons;detailModal.classList.add('open')}));
function form(id,status,label,cls=''){return `<form method="post"><input type="hidden" name="csrf_token" value="${csrf}"><input type="hidden" name="order_id" value="${id}"><input type="hidden" name="status" value="${status}"><button class="btn ${cls}" name="update_status">${label}</button></form>`}
document.querySelectorAll('.ship-btn').forEach(btn=>btn.addEventListener('click',()=>{document.getElementById('shipOrderId').value=btn.dataset.order;document.getElementById('shipNumber').textContent='คำสั่งซื้อ #'+btn.dataset.number;shippingModal.classList.add('open')}));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('.modal').classList.remove('open')));document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open')}));
</script></body></html>
